pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event CallCountTrace(uint256 count);

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256[] calldata v) public {
        // Ensure arrays non-empty and same length
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Track the number of external calls from contract
        uint256 startCount = c.callCount();

        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, caddress, _tos, v));
        require(ok, "transfer reverted");

        uint256 endCount = c.callCount();

        // The reference version makes exactly _tos.length calls via `caddress.call(...)`
        // The mutant makes zero calls.
        assertTrue(endCount - startCount == _tos.length, "call count mismatch");
    }
}

